column7:
monstersetting(v, {
    fixdir=true, --释放技能固定方向，不转向
    ignoreattack={
        type=2, --类型，1=忽略所有人，2=忽略攻击指定玩家的ID，其他的后续再加
        players={tonumber(actor:toString())}
    },
    attacks={
        {
            --1=敌人，2=友方（不包含自己）,3=友方（包含自己）,4=自己，5=玩家，6=红名，7=归属(针对宠物和伙伴的主人)
            --8=指定配置ID的怪物,-9指定唯一ID的怪物
            type=1,
        },
        {
            --1=敌人，2=友方（不包含自己）,3=友方（包含自己）,4=自己，5=玩家，6=红名，7=归属(针对宠物和伙伴的主人)
            --8=指定配置ID的怪物,-9指定唯一ID的怪物
            type=8,
            monsterconfigid={47001}, --可以设置怪物配置ID
        },
        {
            --1=敌人，2=友方（不包含自己）,3=友方（包含自己）,4=自己，5=玩家，6=红名，7=归属(针对宠物和伙伴的主人)
            --8=指定配置ID的怪物,-9指定唯一ID的怪物
            type=9,
            monsterid={} -- 可以设置怪物唯一ID
        }
    }
})

