column7:
-- 将背包中索引为 5 的道具移动到索引为 10 的位置
local indexList = {
    { srcindex = 5, targetindex = 10, count = 0 }
}
local results = moveitem(actor, indexList)

-- 批量移动多个道具
local indexList = {
    { srcindex = 3, targetindex = 8, count = 0 },
    { srcindex = 12, targetindex = 1, count = 0 }
}
local results = moveitem(actor, indexList)

-- 检查每次移动是否成功
for i, ok in ipairs(results) do
    if ok then
        print("第" .. i .. "次移动成功")
    else
        print("第" .. i .. "次移动失败")
    end
end

-- 拆分可堆叠道具，将索引 6 处的道具拆出 10 个移动到索引 15
local indexList = {
    { srcindex = 6, targetindex = 15, count = 10 }
}
local results = moveitem(actor, indexList)
